<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Application\Listener;

use Civi\Lughauth\Features\Document\Rendering\Application\Service\DocumentAssetDumpService;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Event\TemplateAssetDeleteEvent;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Event\TemplateAssetEvent;

/**
 * Keeps the local .assets/templates/ directory in sync with the database.
 *
 * Registered for TemplateAssetEvent so it handles all sub-events (Create, Update,
 * Enable, Disable, Delete) via a single listener entry.
 *
 * - Delete  → remove the file from disk (blob already gone from storage).
 * - Others  → write to disk when enabled; remove when disabled.
 */
class TemplateAssetDiskSyncListener
{
    public function __construct(
        private readonly DocumentAssetDumpService $assetDumpService,
    ) {
    }

    public function __invoke(TemplateAssetEvent $event): void
    {
        if ($event instanceof TemplateAssetDeleteEvent) {
            $this->assetDumpService->removeTemplateAsset($event->payload);
        } else {
            $this->assetDumpService->dumpTemplateAsset($event->payload);
        }
    }
}
